package org.apache.commons.jxpath.ri.compiler;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.jxpath.Pointer;
import org.apache.commons.jxpath.ri.EvalContext;
import org.apache.commons.jxpath.ri.InfoSetUtil;
import org.apache.commons.jxpath.ri.axes.InitialContext;
import org.apache.commons.jxpath.ri.axes.SelfContext;
import org.apache.commons.jxpath.ri.compiler.CoreOperationCompare;
import org.apache.commons.jxpath.ri.compiler.Expression;
import org.apache.commons.jxpath.ri.context.EvalContext;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for CoreOperationCompare.equal
 */
public class CoreOperationCompare_equal_TriageGen2Test {

    private TestableCoreOperationCompare compare;
    private EvalContext mockContext;
    private Expression mockLeft;
    private Expression mockRight;

    // Subclass to expose the protected method and mock the helper methods
    private static class TestableCoreOperationCompare extends CoreOperationCompare {
        boolean containsResult = false;
        boolean findMatchResult = false;
        Object nextEqualResult = false;

        // We need a dummy constructor for the base class
        public TestableCoreOperationCompare() {
            super(null, null);
        }

        @Override
        protected boolean contains(Iterator it, Object value) {
            return containsResult;
        }

        @Override
        protected boolean findMatch(Iterator lit, Iterator rit) {
            return findMatchResult;
        }

        @Override
        protected boolean equal(Object l, Object r) {
            // This is the recursive call to the object equality method
            return nextEqualResult;
        }

        // Expose the protected equal method for testing
        @Override
        public boolean equal(EvalContext context, Expression left, Expression right) {
            return super.equal(context, left, right);
        }
    }

    @Before
    public void setUp() {
        compare = new TestableCoreOperationCompare();
        mockContext = mock(EvalContext.class);
        mockLeft = mock(Expression.class);
        mockRight = mock(Expression.class);
    }

    @Test
    public void testEqual_SimpleObjects() {
        when(mockLeft.compute(mockContext)).thenReturn("A");
        when(mockRight.compute(mockContext)).thenReturn("A");
        compare.nextEqualResult = true;

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_NullObjects() {
        when(mockLeft.compute(mockContext)).thenReturn(null);
        when(mockRight.compute(mockContext)).thenReturn(null);
        compare.nextEqualResult = true;

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_LeftIsInitialContext() {
        InitialContext ctx = mock(InitialContext.class);
        Object node = new Object();
        when(ctx.getSingleNodePointer()).thenReturn(node);
        when(mockLeft.compute(mockContext)).thenReturn(ctx);
        when(mockRight.compute(mockContext)).thenReturn("val");
        compare.nextEqualResult = true;

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
        verify(ctx).getSingleNodePointer();
    }

    @Test
    public void testEqual_RightIsSelfContext() {
        SelfContext ctx = mock(SelfContext.class);
        Object node = new Object();
        when(ctx.getSingleNodePointer()).thenReturn(node);
        when(mockLeft.compute(mockContext)).thenReturn("val");
        when(mockRight.compute(mockContext)).thenReturn(ctx);
        compare.nextEqualResult = true;

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
        verify(ctx).getSingleNodePointer();
    }

    @Test
    public void testEqual_LeftIsCollection() {
        List<String> list = Arrays.asList("item");
        when(mockLeft.compute(mockContext)).thenReturn(list);
        when(mockRight.compute(mockContext)).thenReturn("item");
        // After collection conversion, left becomes an Iterator
        // Since Right is not an Iterator, it triggers contains(Iterator, Object)
        compare.containsResult = true;

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_RightIsCollection() {
        List<String> list = Arrays.asList("item");
        when(mockLeft.compute(mockContext)).thenReturn("item");
        when(mockRight.compute(mockContext)).thenReturn(list);
        // After collection conversion, right becomes an Iterator
        // Since Left is not an Iterator, it triggers contains(Iterator, Object)
        compare.containsResult = true;

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_BothAreIterators() {
        Iterator<String> it1 = Collections.singletonList("A").iterator();
        Iterator<String> it2 = Collections.singletonList("A").iterator();
        when(mockLeft.compute(mockContext)).thenReturn(it1);
        when(mockRight.compute(mockContext)).thenReturn(it2);
        compare.findMatchResult = true;

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_BothAreCollections() {
        // Collection -> Iterator -> findMatch
        List<String> list1 = Arrays.asList("A");
        List<String> list2 = Arrays.asList("A");
        when(mockLeft.compute(mockContext)).thenReturn(list1);
        when(mockRight.compute(mockContext)).thenReturn(list2);
        compare.findMatchResult = true;

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    @Test
    public void testEqual_LeftIsContextAndCollection() {
        // Testing branch where object is both InitialContext and Collection 
        // Note: In real JXPath, context objects usually don't implement Collection, 
        // but we test the logic flow.
        class ContextCollection extends InitialContext implements Collection<Object> {
            @Override public Iterator<Object> iterator() { return Collections.emptyIterator(); }
            @Override public Object getSingleNodePointer() { return new Object(); }
            // Implement other collection methods as needed...
            @Override public int size() { return 0; }
            @Override public boolean isEmpty() { return true; }
            @Override public boolean contains(Object o) { return false; }
            @Override public Iterator<Object> iterator() { return Collections.emptyIterator(); }
            @Override public Object[] toArray() { return new Object[0]; }
            @Override public <T> T[] toArray(T[] a) { return null; }
            @Override public boolean add(Object o) { return false; }
            @Override public boolean remove(Object o) { return false; }
            @Override public boolean containsAll(Collection<?> c) { return false; }
            @Override public boolean addAll(Collection<? extends Object> c) { return false; }
            @Override public boolean removeAll(Collection<?> c) { return false; }
            @Override public boolean retainAll(Collection<?> c) { return false; }
            @Override public void clear() {}
        }

        ContextCollection cc = new ContextCollection();
        when(mockLeft.compute(mockContext)).thenReturn(cc);
        when(mockRight.compute(mockContext)).thenReturn("val");
        compare.containsResult = true;

        assertTrue(compare.equal(mockContext, mockLeft, mockRight));
    }

    // Mock classes to satisfy instanceof checks
    private abstract static class InitialContext implements EvalContext {}
    private abstract static class SelfContext implements EvalContext {}
}
